WITH cte AS ( SELECT cc.cc_call_center_id, cc.cc_name, cc.cc_employees, CASE WHEN cc.cc_employees > 500 THEN 'Large' WHEN cc.cc_employees BETWEEN 200 AND 500 THEN 'Medium' ELSE 'Small' END AS size_category, sm.sm_type AS ship_type, SUM(cs.cs_net_profit) AS total_net_profit, SUM(cs.cs_net_paid) AS total_net_paid, SUM(cs.cs_net_profit) / NULLIF(SUM(cs.cs_net_paid), 0) * 100 AS profit_margin_pct, RANK() OVER (ORDER BY SUM(cs.cs_net_profit) DESC) AS profit_rank FROM catalog_sales cs JOIN call_center cc ON cs.cs_call_center_sk = cc.cc_call_center_sk JOIN ship_mode sm ON cs.cs_ship_mode_sk = sm.sm_ship_mode_sk GROUP BY cc.cc_call_center_id, cc.cc_name, cc.cc_employees, sm.sm_type ) SELECT cc_call_center_id, cc_name, size_category, ship_type, total_net_profit, total_net_paid, profit_margin_pct, ROUND(total_net_profit / SUM(total_net_profit) OVER (), 4) AS profit_share, profit_rank FROM cte WHERE profit_rank <= 5 ORDER BY profit_rank
